async function exportStampedInvoice(cid){const r=dbState.invoiceReviews[approvalKey(cid)];if(!r){toast('Bitte zuerst eine Rechnung einlesen und prüfen.');return}if(r.needsRecheck||r.expectedCents!==billed(cid).totalCents){toast('Stundenabrechnung geändert. Bitte Rechnung erneut prüfen.');return}try{toast('Suche freie Stempelfläche und erstelle Prüfkopie …');const file=await fileStore('get',r.fileKey);if(!file)throw Error('Original-PDF fehlt in diesem Browser.');const sums=retentionTotals(dbState.invoiceReviews,r,dbState.retentionReleases),originalBytes=await file.arrayBuffer(),pdfBytes=/\.xml$/i.test(r.fileName)?await xmlInvoicePdf(originalBytes,r):originalBytes,stamped=await stampInvoice(pdfBytes,r,sums);download(new Blob([stamped.bytes],{type:'application/pdf'}),`DaSo_Pruefkopie_${(r.invoiceNumber||r.week).replace(/[^a-z0-9_-]/gi,'_')}.pdf`);toast('Prüfvermerk auf Seite 1 erstellt.'+(stamped.removedBlankPages?' Leerseiten entfernt.':'')+' PDF heruntergeladen.')}catch(err){toast('PDF konnte nicht erstellt werden: '+err.message)}}
function projectContext(p,fn){const previous=project;project=p;try{return fn()}finally{project=previous}}
function printReports(html,title){let el=$('.printsection');if(!el){el=document.createElement('div');el.className='printsection';document.body.append(el)}el.innerHTML=html;const previous=document.title;document.title=title;window.print();document.title=previous;}
function allWeeksPage(){return sourceWeekPage();}
function bulkTimesheets(){const groups=selectedGroups();if(!groups.length){toast('Keine Nachunternehmerdaten in dieser Auswahl vorhanden.');return}modal(`Alle Stundenzettel · ${groups.length} einzelne PDFs`,`<p>Für jeden Nachunternehmer und jedes Projekt wird für ${esc(week)} eine eigene PDF-Datei erzeugt. Der Download enthält alle PDFs als ZIP-Datei.</p><ul>${groups.map(g=>`<li>${esc(g.firm)} · ${esc(g.project)}</li>`).join('')}</ul>`,btn('Schließen','cancel')+btn('Einzel-PDFs als ZIP herunterladen','bulk-download','download',true));$('#overlay [data-action="bulk-download"]').onclick=async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='PDFs werden erstellt …';try{const files=[];for(const g of groups){const sheet=projectContext(g.project,()=>{const cid=companyIdFor(g.firm),b=billed(cid),a=adjustmentFor(cid),correction=dbState.expectedCorrections[approvalKey(cid)];return{firm:g.firm,project:g.project,week,period:fmt(weekStart(week))+' – '+fmt(addDays(weekStart(week),6)),rows:g.rows,minutes:g.minutes,costCents:b.totalCents,adjustmentTitle:adjustmentHeading(a),adjustmentNote:a.note||a.reason||'',adjustments:[...(a.fitterHours?['Monteur Ausgleich: '+num(a.fitterHours)+' Std.']:[]),...(a.foremanHours?['Obermonteur Ausgleich: '+num(a.foremanHours)+' Std.']:[]),...(a.hours?['Ausgleich: '+num(a.hours)+' Std.']:[]),...(a.by?['Bearbeiter: '+a.by]:[]),...(correction?['Abrechnungskorrektur: '+correction.reason+' / '+correction.by]:[])]}});let name=sheetFilename(sheet),suffix=0;while(files.some(f=>f.name===name))name=sheetFilename(sheet,++suffix);files.push({name,bytes:await timesheetPdf(sheet)});}download(new Blob([zipFiles(files)],{type:'application/zip'}),`DaSo_Stundenzettel_${week}.zip`);toast(files.length+' einzelne PDFs erstellt.');closeModal();}catch(err){toast('Export fehlgeschlagen: '+err.message);button.disabled=false;button.textContent='Erneut herunterladen';}};}
function revenueScopeSwitch(){return '';}
function revenuePage(){return subRevenuePage()+sourceCostWarning();}
function periodRows(rows){return rows.filter(r=>(!project||r.project===project)&&(revenueMode==='month'?r.day.startsWith(month):r.day>=weekStart(week)&&r.day<=addDays(weekStart(week),6)));}
function allRevenuePage(){return subRevenuePage();}
function sourceCostWarning(){const months=revenueMode==='month'?[month]:[...new Set(daysFor(week).map(d=>d.slice(0,7)))];const mismatches=readReport.filter(r=>months.includes(r.month)&&r.companyCostDiffCents);return mismatches.length?`<div class="note amber">${ic('alert')}<span>Quellenhinweis: Die API-Firmenübersicht meldet für ${mismatches.map(r=>r.month).join(', ')} eine abweichende Kostensumme. Hier gelten die Kosten aus den Tages-/Teamwerten der aktualisierten API. Details unter „Datenstand“.</span></div>`:'';}
function displayAufmassMonth(month){
  const cents=subcontractorRevenueTotal(sourceRows.filter(row=>row.binding&&row.day.startsWith(month)));
  return cents===null?'Offen':money(cents);
}
function dataReadDetails(){return`<p class="listtext">Aufmaßdaten ausschließlich lesend. Nur Nachunternehmer werden angezeigt. Datenstand: ${esc(readData.fetchedAt?new Date(readData.fetchedAt).toLocaleString('de-DE',{timeZone:'Europe/Berlin'}):'unbekannt')}.</p><div class="tablewrap"><table><thead><tr><th>Monat</th><th class="num">NU-Umsatz</th><th class="num">NU-Kosten</th></tr></thead><tbody>${readReport.map(r=>`<tr><td>${r.month}</td><td class="num">${displayAufmassMonth(r.month)}</td><td class="num">${money(r.costCents)}</td></tr>`).join('')}</tbody></table></div>${sourceCostWarning()}<div class="note amber">Die aktualisierte API /api/sub-teams liefert Teams und erfasste Teamstunden. ${sourceRows.length} Tages-/Teamwerte wurden übernommen. ${sourceRows.filter(r=>r.estimated).length} davon sind in der Quelle als geschätzt gekennzeichnet – diese Kennzeichnung ist ein Hinweis und sperrt keine Aktion. Keine manuelle Monteurzuordnung, keine Stundenhochrechnung.</div><p class="small muted">Schreibweisen von Oleksii Kompanets werden ausschließlich in diesem Tool unter einem Firmennamen zusammengeführt. Die Originalschreibweise bleibt im Export nachvollziehbar.</p>`;}
function exportAllRevenue(){exportRevenue();}
function companyIdFor(firm){return companyForFirm(dbState.companies,firm)?.id;}
function selectedGroups(){return workingGroups(project).filter(g=>!firmFilter||companyIdFor(g.firm)===firmFilter);}
function sourceTable(g,showRevenue=true){const teams=[...new Set(g.rows.map(r=>r.team))];return`<div class="tablewrap"><table><thead><tr><th>Team laut Aufmaß</th>${daysFor(week).map((d,i)=>`<th class="num">${['Mo','Di','Mi','Do','Fr','Sa','So'][i]}<br><small>${short(d)}</small></th>`).join('')}<th class="num">Stunden</th><th class="num">Kosten</th></tr></thead><tbody>${teams.map(team=>{const rr=g.rows.filter(r=>r.team===team),minutes=knownSum(rr,'minutes'),cost=knownSum(rr,'costCents');return`<tr><td><b>${esc(team||'Team nicht übermittelt')}</b>${rr.some(r=>r.estimated)?'<small class="red-text">Verteilung geschätzt</small>':''}${rr.some(r=>r.manual)?'<small class="muted">Manuell bearbeitet</small>':''}</td>${daysFor(week).map(d=>{const dd=rr.filter(r=>r.day===d),m=knownSum(dd,'minutes'),c=knownSum(dd,'costCents');return`<td class="num">${m===null?'–':num(m/60)+' Std.'}${showRevenue?`<small class="dailycost">Umsatz ${subcontractorRevenueTotal(dd)===null?'–':money(subcontractorRevenueTotal(dd))}</small>`:''}<small class="dailycost">Kosten ${c===null?'–':money(c)}</small></td>`}).join('')}<td class="num sum">${minutes===null?'–':num(minutes/60)}</td><td class="num sum">${cost===null?'Offen':money(cost)}</td></tr>`}).join('')}</tbody></table></div>`;}
function sourceCard(g){const revenue=g.revenueCents===null?null:subcontractorRevenueTotal(g.rows.filter(row=>row.revenueCents!==null));const cid=companyIdFor(g.firm),b=projectContext(g.project,()=>billed(cid)),adj=projectContext(g.project,()=>adjustmentFor(cid)),attrs=`data-company="${esc(cid)}" data-project="${esc(g.project)}"`;return`<section class="card"><div class="cardhead"><div class="companytitle"><span class="companyicon">${ic('company')}</span><div><h2>${esc(g.firm)}</h2><small>${esc(g.project)} · ${g.rows.length} Aufmaß-Tageswerte</small></div>${badge(g.edited?'Manuell bearbeitet':'Aus Aufmaß',g.edited?'amber':'green')}${g.sourceChanged?badge('Quelle zwischenzeitlich geändert','amber'):''}</div><div class="actions">${btn('Bearbeiten','week-edit','edit',false,attrs)}${btn('Rechnung einlesen','invoice-review','doc',false,attrs)}${btn('Stundenzettel','sheet-project','print',false,attrs)}</div></div>${sourceTable(g)}<div class="adjustline"><div><span class="small muted">NU-Umsatz: <b>${revenue===null?'Offen':money(revenue)}</b></span><span class="small muted">Wochenkosten: <b>${b.totalCents===null?'Offen':money(b.totalCents)}</b></span><span class="small muted">Gewinn: <b class="${revenue!==null&&b.totalCents!==null&&revenue-b.totalCents<0?'red-text':'green-text'}">${revenue===null||b.totalCents===null?'Offen':money(revenue-b.totalCents)}</b></span>${projectContext(g.project,()=>adjustmentSummary(cid,b))}</div>${btn('Bonus / Abzug','adjust','plus',false,attrs)}</div><div class="cardfoot"><div class="total">Wochenpauschale netto <strong>${b.totalCents===null?'Offen':money(b.totalCents)}</strong></div><small>${g.minutes===null?'Stunden offen':num(g.minutes/60)+' Arbeitsstunden'}${g.minutes!==null?' · '+num(g.minutes/60+b.adjustmentHours)+' Abrechnungsstunden':''}</small></div>${projectContext(g.project,()=>invoiceCardSummary(cid)).replaceAll('data-company=','data-project="'+esc(g.project)+'" data-company=')}</section>`;}
function unassignedCard(){
  if(!dbState.settings.nuMaster)return '';
  const firms=new Map();
  for(const g of sourceGroups(sourceRows,week,project,'').filter(g=>!companyIdFor(g.firm))){const f=firms.get(g.firm)||{projects:new Set(),rows:0};f.projects.add(g.project);f.rows+=g.rows.length;firms.set(g.firm,f)}
  if(!firms.size)return '';
  return `<section class="card"><div class="cardhead"><div class="companytitle"><span class="companyicon">${ic('info')}</span><div><h2>Nicht zugeordnet</h2><small>Aufmaß-Stunden von Firmen, die es in diesem Tool nicht gibt</small></div></div></div><div class="tablewrap"><table><thead><tr><th>Firma laut Aufmaß</th><th>Projekte</th><th>Tageswerte</th><th></th></tr></thead><tbody>${[...firms].map(([name,f])=>`<tr><td><b>${esc(name)}</b></td><td>${esc([...f.projects].join(', '))}</td><td>${f.rows}</td><td>${btn('Firma anlegen','company-new','plus',false,`data-name="${esc(name)}"`)}${btn('Vorhandener Firma zuordnen','firm-alias','edit',false,`data-name="${esc(name)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function sourceWeekPage(){const groups=selectedGroups(),rows=groups.flatMap(g=>g.rows),minutes=knownSum(rows,'minutes'),adjustedHours=groups.reduce((s,g)=>s+projectContext(g.project,()=>billed(companyIdFor(g.firm)).adjustmentHours),0),cost=groups.length&&groups.every(g=>projectContext(g.project,()=>billed(companyIdFor(g.firm)).totalCents)!==null)?groups.reduce((s,g)=>s+projectContext(g.project,()=>billed(companyIdFor(g.firm)).totalCents),0):null,printable=groups,ps=[...new Set(groups.map(g=>g.project))];return heading('AUFMASS · NACHUNTERNEHMER','Wochenübersicht','Teams, Stunden und Kosten so übernehmen, wie sie im Aufmaß erfasst wurden.',btn('CSV exportieren','export-hours','download',false,rows.length?'':'disabled')+btn(`Alle Stundenzettel (${printable.length})`,'bulk-timesheets','print',true,printable.length?'':'disabled')+btn('Datenstand','integration','info'))+filters()+`<div class="stats">${stat('Abrechnungsstunden',minutes===null?'–':num(minutes/60+adjustedHours)+' Std.',minutes===null?'Stunden teilweise offen':num(minutes/60)+' erfasst · '+(adjustedHours>0?'+':'')+num(adjustedHours)+' Ausgleich','clock')}${stat('Wochenpauschale',cost===null?'–':money(cost),'Aufmaßkosten plus Bonus / Abzug','euro','focus')}${stat('Nachunternehmer',groups.length?String(new Set(groups.map(g=>g.firm)).size):'–',`${ps.length} Projekte mit Aufmaßdaten`,'company')}${stat('Stundenzettel',String(printable.length),'Je Projekt und Nachunternehmer','doc')}</div>${!sourceDetailed?`<div class="note amber">${ic('info')}<span><strong>Aufmaß-Umsätze und Kosten sind übernommen.</strong> Die aktuelle Lese-API übermittelt keine Teams oder Stunden. Diese Angaben bleiben offen; Stundenzettel werden erst mit den Aufmaß-Teamstunden freigeschaltet. Es ist keine Mitarbeiterzuordnung erforderlich.</span></div>`:`<div class="note">${ic('info')}<span>Teams und Stunden sind aus der aktualisierten API übernommen. Fehlende Angaben bleiben offen. ${rows.some(r=>r.estimated)?rows.filter(r=>r.estimated).length+' Tages-/Teamwerte sind als geschätzt gekennzeichnet. Du kannst die Angaben bei Bedarf bearbeiten.':''}</span></div>`}${unassignedCard()}<div class="sectionline"><h2>${project?'Nachunternehmer im Projekt':'Alle Projekte'}</h2><select id="firm-filter" aria-label="Nachunternehmer filtern" class="search" style="min-width:170px;width:auto;padding:7px"><option value="">Alle Nachunternehmer</option>${dbState.companies.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${firmFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${groups.length?ps.map(p=>`${!project?`<div class="sectionline"><h2>${esc(p)}</h2>${btn('Projekt öffnen','project-open','right',false,`data-project="${esc(p)}"`)}</div>`:''}${groups.filter(g=>g.project===p).map(sourceCard).join('')}`).join(''):'<section class="card empty"><h3>Keine Nachunternehmer-Aufmaße in dieser Woche</h3><p>Wähle eine andere Kalenderwoche oder ein anderes Projekt.</p></section>'}<p class="small muted">Nur verbindliche Aufmaßwerte. Fehlende Stunden werden nicht aus Kosten oder Mitarbeiteranzahlen berechnet. Verschiedene Schreibweisen von Oleksii Kompanets gehören zu einer Firma.</p>`;}

function correctedExpected(cid,cents){const c=dbState.expectedCorrections[approvalKey(cid)];return c&&c.sourceExpectedCents===cents?c.cents:cents;}

function workingGroups(p='',firm=''){return sourceGroups(sourceRows,week,p,firm).filter(g=>!dbState.settings.nuMaster||companyIdFor(g.firm)).map(g=>{const key=projectContext(g.project,()=>approvalKey(companyIdFor(g.firm)));return editedGroup(g,dbState.weekEdits[key]);});}
function adjustmentSummary(cid,b,report=false){const a=adjustmentFor(cid),r=roleAdjustment(a,agreementFor(cid,project));const title=adjustmentHeading(a);if(!a.fitterHours&&!a.foremanHours&&!a.hours&&!a.note&&!a.reason)return report?'':'<span class="small muted">Kein Bonus / Abzug</span>';const label=r.legacy?`${num(a.hours)} Stunden`:`Monteur ${Number(a.fitterHours)>0?'+':''}${num(a.fitterHours||0)} Std. · Obermonteur ${Number(a.foremanHours)>0?'+':''}${num(a.foremanHours||0)} Std.`;return`<${report?'p':'span'} class="${report?'':'adjustbadge'}">${report&&title?`<strong style="display:block">${esc(title)}</strong>`:''}${esc(label)} · ${b.adjustmentCents===null?'Projektsatz fehlt':money(b.adjustmentCents)}${(a.note||a.reason)?`<span style="display:block;white-space:pre-wrap;overflow-wrap:anywhere">Notiz: ${esc(a.note||a.reason)}</span>`:''}</${report?'p':'span'}>`;}
function editWeekModal(cid){const g=sourceGroup(cid);if(!g)return;const raw=sourceGroups(sourceRows,week,project).find(x=>x.firm===g.firm),key=approvalKey(cid),a=agreementFor(cid,project),items=g.rows.map(r=>({...r})),teams=[...new Set(items.map(r=>r.team||'Team'))];for(const team of teams)for(const day of daysFor(week))if(!items.some(r=>(r.team||'Team')===team&&r.day===day))items.push({id:`manual:${week}:${team}:${day}`,day,team,firm:g.firm,project:g.project,minutes:null,fitterMinutes:null,foremanMinutes:null,revenueCents:null,costCents:null,binding:true,estimated:false});items.sort((a,b)=>String(a.team).localeCompare(String(b.team))||a.day.localeCompare(b.day));const input=(i,field,value,type='number')=>`<input name="${i}-${field}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="any" min="0"':''} style="width:${type==='text'?70:95}px" aria-label="${esc(items[i].team||'Team')} ${items[i].day} ${field}">`;modal('Wochenwerte bearbeiten',`<form id="week-edit-form"><p class="small muted">Umsatz fest aus dem Aufmaß. Rollenaufteilung bei Bedarf manuell eingeben; ein leeres Rollenfeld zählt dann als 0. Ohne neue Aufteilung bleiben vorhandene Gesamtstunden und Kosten erhalten.</p><p class="small muted">Projektsätze: Monteur ${a?.fitterRateCents==null?'offen':money(a.fitterRateCents)} / Std. · Obermonteur ${a?.foremanRateCents==null?'offen':money(a.foremanRateCents)} / Std.</p><div class="tablewrap"><table><thead><tr><th>Team</th><th>Datum</th><th>Monteur Std.</th><th>Obermonteur Std.</th><th>Gesamt Std.</th><th>Umsatz €</th><th>Kosten €</th></tr></thead><tbody>${items.map((r,i)=>`<tr><td>${input(i,'team',r.team||'Team','text')}</td><td>${short(r.day)}</td><td>${input(i,'fitterMinutes',r.fitterMinutes==null?'':r.fitterMinutes/60)}</td><td>${input(i,'foremanMinutes',r.foremanMinutes==null?'':r.foremanMinutes/60)}</td><td class="num" id="edit-hours-${i}">${r.minutes===null?'–':num(r.minutes/60)}</td><td class="num">${aufmassValue(r)===null?'–':money(aufmassValue(r))}</td><td class="num" id="edit-cost-${i}">${r.costCents===null?'Offen':money(r.costCents)}</td></tr>`).join('')}</tbody></table></div><p id="week-edit-error" class="inlineerror"></p></form>`,btn('Abbrechen','cancel')+btn('Aufmaßwerte wiederherstellen','week-restore','left')+'<button class="btn primary" form="week-edit-form" type="submit">Änderungen übernehmen</button>',true);const changed=new Set();const calculate=(i,f)=>{const r=items[i];if(!changed.has(i))return{...r,team:String(f.get(i+'-team')||'').trim()};const read=field=>{const v=String(f.get(i+'-'+field)||'').trim();if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))throw Error('Rollenstunden prüfen.');return Math.round(Number(v||0)*60);};return{...r,team:String(f.get(i+'-team')||'').trim(),...roleDayCost(read('fitterMinutes'),read('foremanMinutes'),a),rates:{fitterRateCents:a?.fitterRateCents??null,foremanRateCents:a?.foremanRateCents??null}};};$('#week-edit-form').oninput=e=>{const match=e.target.name.match(/^(\d+)-(fitterMinutes|foremanMinutes)$/);if(!match)return;const i=Number(match[1]);changed.add(i);try{const r=calculate(i,new FormData($('#week-edit-form')));$('#edit-hours-'+i).textContent=num(r.minutes/60);$('#edit-cost-'+i).textContent=r.costCents===null?'Projektsatz fehlt':money(r.costCents);$('#week-edit-error').textContent='';}catch(error){$('#week-edit-error').textContent=error.message;}};$('#overlay [data-action="week-restore"]').onclick=()=>{delete dbState.weekEdits[key];if(dbState.invoiceReviews[key])dbState.invoiceReviews[key].needsRecheck=true;persist();closeModal();shell();};$('#week-edit-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),patches={},added=[];items.forEach((r,i)=>{const rr=calculate(i,f),orig=raw.rows.find(x=>x.id===r.id);if(!orig&&!changed.has(i)&&rr.minutes===null&&rr.costCents===null)return;if(!rr.team)throw Error('Teambezeichnung ergänzen.');if(orig){const patch={};for(const field of ['team','minutes','fitterMinutes','foremanMinutes','costCents','rates'])if(JSON.stringify(rr[field])!==JSON.stringify(orig[field]))patch[field]=rr[field];if(Object.keys(patch).length)patches[r.id]=patch;}else added.push(rr);});dbState.weekEdits[key]={patches,added,baseSignature:JSON.stringify(raw.rows),at:new Date().toISOString()};if(dbState.invoiceReviews[key])dbState.invoiceReviews[key].needsRecheck=true;if(!persist())return;closeModal();shell();}catch(error){$('#week-edit-error').textContent=error.message;}};}

function retentionPage(){const c=company(detailCompany);if(!c)return companiesPage();const groups=retentionLedger(dbState.invoiceReviews,dbState.retentionReleases,c.id),withheld=groups.reduce((s,g)=>s+g.withheldCents,0),paid=groups.reduce((s,g)=>s+g.paidCents,0),open=groups.reduce((s,g)=>s+g.openCents,0),planned=groups.reduce((s,g)=>s+g.plannedCents,0);return heading('NACHUNTERNEHMER · SICHERHEITSEINBEHALTE',esc(c.name),'Einbehalte nach Rechnung und Projekt, Auszahlungen und Protokolle.',btn('Alle Firmen','company-back','left')+btn('Firma archivieren','company-archive','doc',false,`data-company="${detailCompany}"`))+`<div class="subtabs"><button data-action="detail-tab" data-tab="company">Firma & Unterlagen</button><button data-action="detail-tab" data-tab="workers">Teams & Mitarbeiter</button><button data-action="detail-tab" data-tab="contracts">Projekte & Verträge</button><button data-action="detail-tab" data-tab="retention" class="active">Sicherheitseinbehalte</button></div><div class="stats">${stat('Einbehalte erfasst',money(withheld),'Aus geprüften Rechnungen','euro')}${stat('Ausbezahlt erfasst',money(paid),'Manuell dokumentierte Auszahlungen','check')}${stat('Noch offen',money(open),'Erfasste Einbehalte minus Auszahlungen','euro','focus')}${stat('Zur Auszahlung vorbereitet',money(planned),'Für vorbereitete Auszahlungen reserviert','clock')}</div>${groups.length?groups.map(g=>{let cumulative=0;return`<section class="card"><div class="cardhead"><div><h2>${esc(g.project)}</h2><small>${g.rows.length} Rechnungen · Offen ${money(g.openCents)}${g.plannedCents?' · Vorgemerkt '+money(g.plannedCents):''}</small></div>${btn('Einbehalt auszahlen','retention-release','euro',true,`data-project="${esc(g.project)}"`)}</div>${g.availableCents<0?'<div class="note amber">Die erfassten Auszahlungen/Vormerkungen übersteigen die aktuellen Einbehalte. Rechnungsänderungen und Buchungen prüfen.</div>':''}<div class="tablewrap"><table><thead><tr><th>Rechnung</th><th>Datum</th><th>Status</th><th class="num">Einbehalt</th><th class="num">Kumuliert</th></tr></thead><tbody>${g.rows.map(r=>{cumulative+=r.retentionCents;return`<tr><td><b>${esc(r.invoiceNumber||r.fileName||'Ohne Nummer')}</b></td><td>${esc(r.paymentDate?fmt(r.paymentDate):r.reviewedDate?fmt(r.reviewedDate):'Offen')}</td><td>${badge(r.paid?'Rechnung als überwiesen erfasst':'Rechnung zur Zahlung vorbereitet',r.paid?'green':'amber')}</td><td class="num">${money(r.retentionCents)}</td><td class="num sum">${money(cumulative)}</td></tr>`}).join('')}</tbody></table></div><div class="cardfoot"><span>Gesamt ${money(g.withheldCents)}</span><span>Ausbezahlt ${money(g.paidCents)}</span><strong>Offen ${money(g.openCents)}</strong></div>${g.payments.length?`<div class="tablewrap"><table><thead><tr><th>Auszahlung</th><th>Status</th><th>Geprüft von</th><th class="num">Betrag</th><th></th></tr></thead><tbody>${g.payments.map(r=>`<tr><td>${fmt(r.paymentDate)}</td><td>${badge(r.status==='paid'?'Ausbezahlt erfasst':'Vorbereitet',r.status==='paid'?'green':'amber')}</td><td>${esc(r.reviewer)}</td><td class="num">${money(r.amountCents)}</td><td><div class="actions">${btn('Protokoll / PDF','retention-protocol','download',false,`data-id="${r.id}"`)}${r.status==='planned'?btn('Als ausbezahlt erfassen','retention-paid','check',false,`data-id="${r.id}"`):''}${btn('Stornieren','retention-cancel','close',false,`data-id="${r.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:''}</section>`}).join(''):'<section class="card empty"><h3>Noch keine Sicherheitseinbehalte erfasst</h3><p>Sobald eine geprüfte Rechnung einen Sicherheitseinbehalt enthält, erscheint sie hier mit Projekt, Datum und Betrag.</p></section>'}<p class="small muted">Basiert auf den hier erfassten Rechnungsprüfungen und Auszahlungsvermerken. Vorbereitete Rechnungen/Auszahlungen sind entsprechend gekennzeichnet. Keine automatische Bankbuchung.</p>`;}
function releaseModal(p){const cid=detailCompany,g=retentionLedger(dbState.invoiceReviews,dbState.retentionReleases,cid).find(x=>x.project===p);if(!g)return;if(g.availableCents<=0){toast('Für dieses Projekt ist kein weiterer Einbehalt zur Auszahlung verfügbar.');return}modal('Sicherheitseinbehalt auszahlen',`<form id="release-form" class="formgrid"><p class="span2"><b>${esc(cname(cid))}</b><br>${esc(p)}<br>Verfügbarer Einbehalt: ${money(g.availableCents)}</p>${formField('Auszahlungsbetrag (€)','amount',g.availableCents/100,'number','min="0.01" step="0.01" required')}${formField('Auszahlungsdatum','paymentDate',today(),'date','required')}${formField('Geprüft von','reviewer','David Sommerhoff','text','required maxlength="100" list="release-reviewers"')}<datalist id="release-reviewers"><option value="David Sommerhoff"><option value="Sandra Harzenbecker"></datalist>${formField('Abnahme am (optional)','acceptanceDate','','date')}<label class="field span2"><span>Notiz (optional)</span><textarea name="note" maxlength="500"></textarea></label><p id="release-error" class="inlineerror span2"></p></form>`,btn('Abbrechen','cancel')+'<button class="btn primary" form="release-form" type="submit">Auszahlung vorbereiten & Protokoll erstellen</button>');$('#release-form').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),current=retentionLedger(dbState.invoiceReviews,dbState.retentionReleases,cid).find(x=>x.project===p),amountCents=validateRelease(Math.round(Number(f.amount)*100),current.availableCents);if(!f.reviewer.trim())throw Error('Bitte Prüfernamen ergänzen.');const r={id:uid(),companyId:cid,companyName:cname(cid),project:p,amountCents,status:'planned',paymentDate:f.paymentDate,reviewer:f.reviewer.trim(),acceptanceDate:f.acceptanceDate,note:f.note.trim(),withheldCents:current.withheldCents,paidBeforeCents:current.paidCents,openAfterCents:current.openCents-amountCents,items:structuredClone(current.rows),createdAt:new Date().toISOString()};dbState.retentionReleases.push(r);if(!persist())return;closeModal();shell();await exportRetentionProtocol(r.id);}catch(error){if($('#release-error'))$('#release-error').textContent=error.message;else toast(error.message);}};}
async function exportRetentionProtocol(id){const r=dbState.retentionReleases.find(x=>x.id===id);if(!r)return;try{const bytes=await retentionProtocol(r.companyName,r);download(new Blob([bytes],{type:'application/pdf'}),`DaSo_Einbehalt_${r.paymentDate}_${r.id.slice(0,8)}.pdf`);}catch(error){toast('Protokoll konnte nicht erstellt werden: '+error.message);}}
function markRetentionPaid(id){const r=dbState.retentionReleases.find(x=>x.id===id&&x.status==='planned');if(!r)return;modal('Auszahlung als erfolgt erfassen',`<form id="release-paid-form"><p>${esc(r.companyName)} · ${esc(r.project)}<br>${money(r.amountCents)}</p>${formField('Überwiesen am','paymentDate',r.paymentDate,'date','required')}${formField('Erfasst von','reviewer',r.reviewer,'text','required maxlength="100"')}<p id="paid-error" class="inlineerror"></p></form>`,btn('Abbrechen','cancel')+'<button class="btn primary" form="release-paid-form" type="submit">Als ausbezahlt speichern & Protokoll</button>');$('#release-paid-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.paymentDate>today()){$('#paid-error').textContent='Eine erfolgte Auszahlung darf nicht in der Zukunft liegen.';return}if(!f.reviewer.trim())return;const g=retentionLedger(dbState.invoiceReviews,dbState.retentionReleases,r.companyId).find(x=>x.project===r.project);if(!g||r.amountCents>g.openCents){$('#paid-error').textContent='Einbehalt reicht nach aktuellen Rechnungsdaten nicht aus. Bitte prüfen.';return}r.status='paid';r.paymentDate=f.paymentDate;r.reviewer=f.reviewer.trim();r.paidBeforeCents=g.paidCents;r.withheldCents=g.withheldCents;r.openAfterCents=g.openCents-r.amountCents;r.items=structuredClone(g.rows);r.paidAt=new Date().toISOString();if(!persist())return;closeModal();shell();await exportRetentionProtocol(id);};}
function cancelRetentionRelease(id){const r=dbState.retentionReleases.find(x=>x.id===id);if(!r)return;confirmModal('Auszahlungsvermerk stornieren','Der Vermerk wird als storniert erhalten. Die Aufstellung wird neu berechnet.',()=>{r.status='cancelled';r.cancelledAt=new Date().toISOString();persist();closeModal();shell();});}

shell();

function extraCompanyDocs(cid){return dbState.docs.filter(d=>d.companyId===cid&&!d.workerId&&!d.projectAgreementId&&!companyDocTypes.includes(d.type)).map(d=>docRow(d)).join('');}

// Drop zones. Dropped files skip the picker's accept filter, so apply it here.
const acceptsFile=(f,accept)=>!accept||accept.split(',').map(t=>t.trim().toLowerCase()).filter(Boolean).some(t=>t.startsWith('.')?f.name.toLowerCase().endsWith(t):t.endsWith('/*')?f.type.startsWith(t.slice(0,-1)):f.type===t);
const zoneOf=e=>e.target.closest?.('.uploadzone');
document.addEventListener('dragover',e=>{if(!e.dataTransfer?.types.includes('Files'))return;e.preventDefault();const z=zoneOf(e);if(z)z.classList.add('over');else e.dataTransfer.dropEffect='none'});
document.addEventListener('dragleave',e=>{const z=zoneOf(e);if(z&&!z.contains(e.relatedTarget))z.classList.remove('over')});
document.addEventListener('drop',e=>{
  if(!e.dataTransfer?.types.includes('Files'))return;
  e.preventDefault();
  const z=zoneOf(e);if(!z)return;
  z.classList.remove('over');
  const input=z.querySelector('input[type=file]');
  if(!input||input.disabled)return;
  const files=[...e.dataTransfer.files].filter(f=>acceptsFile(f,input.accept));
  if(!files.length){toast('Dieser Dateityp wird hier nicht unterstützt.');return}
  const dt=new DataTransfer();
  for(const f of input.multiple?files:files.slice(0,1))dt.items.add(f);
  input.files=dt.files;
  input.dispatchEvent(new Event('change',{bubbles:true}));
});
document.addEventListener('change',e=>{
  const z=e.target.type==='file'&&e.target.closest?.('.uploadzone');
  if(!z)return;
  let n=z.querySelector('.dz-file');
  if(!n){n=document.createElement('small');n.className='dz-file';z.append(n)}
  n.textContent=[...e.target.files].map(f=>f.name).join(', ');
});
